"""Collate verified local receipts into the existing learning ledger."""
import json, hashlib, struct
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def read(name): return json.loads((ROOT/'evidence'/name).read_text(encoding='utf-8-sig'))
gpu=read('exhibit-gpu-render.json'); native=read('exhibit-packaged-latest.json'); browser=read('exhibit-holodeck-results.json'); audit=read('exhibit-native-material-audit.json')
assert gpu['ok'] and gpu['viewFidelity']['materialFaithful'] and not gpu['viewFidelity']['degraded']
assert native['status']=='passed' and native['dx12sm6'] and len(native['checks'])==5
assert len(browser)==2 and all(not x['errors'] and len(x['checks'])==6 for x in browser)
assert audit['ok']
blob=(ROOT/'authoring/interaction-exhibit.glb').read_bytes()
glb=json.loads(blob[20:20+struct.unpack_from('<I',blob,12)[0]])
summary={'asOf':'2026-10-26','asset':read('exhibit-saved.json')['asset'],'glbSha256':hashlib.sha256(blob).hexdigest(),'glbBytes':len(blob),'meshes':len(glb['meshes']),'materials':len(glb['materials']),'embeddedImages':len(glb['images']),'sourceTriangles':sum(glb['accessors'][p['indices']]['count']//3 for m in glb['meshes'] for p in m['primitives']),'gpu':gpu['viewFidelity'],'native':native,'browser':[{'backend':x['backend'],'checks':x['checks'],'revision':x['observation']['revision'],'errors':x['errors']} for x in browser],'limits':['Native physical keyboard focus not exercised; scripted methods tested in packaged runtime.','Lighting/exposure/reflections differ; no material color equivalence claim.','No normal-map, packed-channel, mip-distance, atlas, LOD or performance qualification.','Same-byte reimport only; changed-source reimport and artist override conflict handling untested.','Diagnostic markers intentionally float. No collision is generated.','Saved revision preview is the initial CPU sheet; separate GPU sheet verifies the identical GLB hash.']}
(ROOT/'evidence/exhibit-summary.json').write_text(json.dumps(summary,indent=2))
ledger=read('integration-learning-ledger.json')
new=[
 {'id':'EXHIBIT-CROSS-ENGINE-001','topic':'asset-to-game interaction','status':'observed-pass-limited','question':'Can one saved portable asset render and interact in both actual runtimes?','observed':'Exact saved GLB rendered in Holodeck WebGPU/WebGL2 and imported into UE5.8.4. Five packaged assertions and six browser checks per backend passed. Both use0.6rad/s and reset to running at zero angle.','sourceHashes':{'glb':summary['glbSha256']},'owner':'destination-adapters-and-gameplay','reuseDecision':'Reuse the small fixture, stable asset identity and separate runtime behavior; keep the native and browser test runners scoped to this workspace.','limits':summary['limits'],'evidence':['evidence/exhibit-summary.json','evidence/exhibit-packaged-latest.json','evidence/exhibit-holodeck-results.json','evidence/exhibit-native-material-audit.json']},
 {'id':'EXHIBIT-IMPORT-FRAME-001','topic':'Unreal import','status':'failure-corrected','question':'Does a single-mesh block establish the import shape of a multipart asset?','observed':'No. The first assertion expected one combined mesh and failed. Interchange produced five named meshes with translations baked into vertices. Identity child transforms under a shared root preserved the assembly; sorted paths, bounds and material references survived reimport. Signed markers verified centimetres [x,z,y]*100.','owner':'unreal-adapter','reuseDecision':'Read back actual asset count and baked transforms. Do not apply source translations twice.','limits':['No arbitrary hierarchy, nonuniform scale or sockets test.'],'evidence':['evidence/exhibit-native-import-first-failure.json','evidence/exhibit-native-import.json','evidence/exhibit-native-material-audit.json']},
 {'id':'KILN-GPU-RETRY-001','topic':'rendering','status':'failure-corrected','question':'Is the workstation limited to CPU previews?','observed':'No. After explicit user retry, the supported service start succeeded on port8010 and RTX3070 Dawn/D3D12 produced full-material views with no degradation. Earlier automatic approval rejection cause remains unknown.','owner':'workspace-renderer-setup','reuseDecision':'Use supported service lifecycle and dedicated port; require actual viewFidelity and hash evidence.','limits':['Saved initial CPU thumbnail was retained as historical evidence.'],'evidence':['evidence/exhibit-gpu-render.json','authoring/interaction-exhibit-gpu.png']},
 {'id':'HOLODECK-EXHIBIT-ADMISSION-001','topic':'world contract','status':'failure-corrected','observed':'Scene proposal validation rejected missing collider and a1.5m eye height. Explicit collider:null and the flat-ground controller required1.72m eye height passed. Browser controls then passed in both backends.','owner':'holodeck-workflow','reuseDecision':'Read controller capabilities and distinguish collision-free from omitted records.','limits':['Applies to the installed flat-ground controller.'],'evidence':['evidence/exhibit-holodeck-proposal.json','evidence/exhibit-holodeck-results.json']},
 {'id':'MATERIAL-COMPARISON-001','topic':'technical art','status':'partial','observed':'Both albedo maps survive import with correct sRGB settings and are visible. Native rendering appears brighter than browser rendering; lighting, exposure and reflection environment are not matched. UE default import enabled Nanite on this tiny asset.','owner':'technical-art-and-destination-adapters','reuseDecision':'Keep portable maps as source; calibrate engine lighting/material bindings before changing albedo. Compare conventional meshes before recommending Nanite.','nextTest':'Controlled neutral lighting, gray card, normal/packed-channel diagnostic, distance mip test, and native material-instance overlay with reimport preservation.','evidence':['evidence/exhibit-native-material-audit.json','evidence/exhibit-packaged-latest.json','evidence/exhibit-holodeck-webgpu.png','evidence/exhibit-holodeck-webgl.png']}
]
ids={e['id'] for e in new}
ledger['entries']=[e for e in ledger['entries'] if e['id'] not in ids]+new
